import json,sys;d=json.load(open("reports/label_quality.json"));num=lambda x:isinstance(x,(int,float));g=lambda dd,k:(dd.get(k) if isinstance(dd,dict) and num(dd.get(k)) else None);rate=next((r for r in [g(d,"agreement"),g(d,"relabel_agreement"),g(d.get("metric"),"agreement"),g(d.get("metric"),"acc"),g(d.get("relabel_agreement"),"agreement")] if r is not None),None);n=next((x for x in [d.get("n"),d.get("sample_n"),d.get("n_relabel")] if x is not None),None);print("agreement=",rate,"n=",n);assert rate is not None,rate;assert float(rate)>=0.70,rate;assert n is not None,n;assert int(n)>0,n